import{_ as o,l as i,o as a,c as B,v as e,p as d,x as r,d as n,i as s,S as A}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Aquila2","description":"","frontmatter":{"title":"Aquila2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aquila2.md","filePath":"llm/aquila2.md","lastUpdated":1789023840000}'),h={name:"llm/aquila2.md"};function p(u,t,E,c,q,g){const l=i("Mermaid");return a(),B("div",null,[t[1]||(t[1]=e('<h1 id="aquila2" tabindex="-1">Aquila2 <a class="header-anchor" href="#aquila2" aria-label="Permalink to &quot;Aquila2&quot;">​</a></h1><div class="epigraph"><p>HeuriMentor 把训练看成可改配比的闭环：监视损失、下游分与权重轨迹，再让数据管理单元换批次，而不是在静态混合上一次跑完 1.8T。</p><footer>—— Zhang 等，Aquila2 Technical Report，arXiv:2408.07410</footer></div><p>智源（BAAI）的 Aquila 一线在 FlagAI / FlagScale 上开源中英双语底座。2024 年 8 月的技术报告给出 <strong>Aquila2-7B / 34B / 70B-expr</strong>，以及对话版 AquilaChat2。结构仍是 LLaMA 式解码器：<a href="/llm/su-rope">RoPE</a>、SwiGLU、RMSNorm；34B 与 70B 用 <a href="/llm/gqa">GQA</a>；词表 BPE <strong>10 万</strong>，在 WuDao 与 Pile 上按中英约各半抽词。真正写进论文标题位置的贡献不是新注意力，而是 <strong>HeuriMentor（HM）</strong>：自适应训练引擎、训练状态监视、数据管理单元三条闭环，用来在预训练中途改数据配比、扩缩集群、甚至在 A100 40G 与 A800 80G 的异构池上继续训。本篇按 2408.07410 写这一代；一代 Aquila-7B/33B 与后来未写入该报告的变体不倒填。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态混合的痛点是：网页、百科、论文、代码、知识密集型标注不是同一天备齐的，也不是同一难度。LLaMA 65B 那种「固定配比、千卡跑三周」在数据还在入库时会被迫二选一——要么等齐再开训，要么开训后无法把新源加进去而不打乱已收敛的表示。双语模型还要面对中英 token 比：报告在 1.3B 探针上看到中文比例过高会抬高整体损失，正式训练把中英比落在大约 1:2 到 1:3。</p><p>第二个问题是监视什么。只看损失会在换知识密集型批次时出现陡降，下游 HELM 分数却不动——那是域变了，不是突然变聪明。需要同时看损失、下游、以及权重轨迹，才能决定「该过滤噪点」还是「该加知识」还是「该停」。</p><h3 id="三档结构不要共用一张层表" tabindex="-1">三档结构不要共用一张层表 <a class="header-anchor" href="#三档结构不要共用一张层表" aria-label="Permalink to &quot;三档结构不要共用一张层表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>型号</th><th>层数</th><th>隐维</th><th>FFN</th><th>头</th><th>GQA</th><th>窗</th><th>学习率</th><th>batch</th></tr></thead><tbody><tr><td>7B</td><td>32</td><td>4096</td><td>11008</td><td>32</td><td>无</td><td>2048</td><td>\\(2\\times 10^{-4}\\)</td><td>1728</td></tr><tr><td>34B</td><td>60</td><td>6144</td><td>24576</td><td>48</td><td>8</td><td>4096</td><td>\\(1.5\\times 10^{-4}\\)</td><td>1024</td></tr><tr><td>70B-expr</td><td>80</td><td>8192</td><td>28672</td><td>64</td><td>8</td><td>4096</td><td>\\(1.5\\times 10^{-4}\\)</td><td>1032</td></tr></tbody></table><p>7B 全头注意力、2K 窗；34B 才是报告主推的双语对照档。70B 明确标 <strong>expr</strong>：预算不够、前两阶段 token 偏少，第三阶段不敢像 34B 那样猛改配比。</p><p><span class="marginnote"> Aquila2-70B-expr 在 A100 40G 与 A800 80G 混部上训，是异构策略实验，不是「70B 已经按 34B 同配方放大」。引用时保留 expr，不要写成正式 70B 生产档。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>HeuriMentor 三件套。<strong>ATE</strong>（自适应训练引擎）：支持中途改集群规模、改模型切分；7B 走数据并行加分布式优化器；34B 加张量并行、1F1B 流水线与序列并行，FlashAttention-2，报告写 34B 约 <strong>666 token/s/GPU</strong>；混合精度主体 bfloat16，词嵌入、RoPE、注意力 softmax、梯度 all-reduce 用 FP32。前 8B token 把 batch 从 32 爬到 1024；AdamW \\(\\beta_1=0.9\\)、\\(\\beta_2=0.95\\)、weight decay 0.1，余弦学习率，梯度裁剪 1.0。<strong>TSM</strong>（训练状态监视）：跟踪损失、下游、权重。权重侧用各层参数标准差的轨迹，以 Fréchet 距离衡量相邻检查点之间每 1B token 的位移 \\(dist(p,i,i+1)\\)，用来看换数据阶段时表示是否被掀翻。<strong>DMU</strong>（数据管理）：网页、百科、论文、教材、代码、知识（问答、学术监督、指令模板化）分源去重过滤，再按批次 K6–K65 改配方。</p><h3 id="语言建模-→-知识-→-任务向-三相位" tabindex="-1">语言建模 → 知识 → 任务向 三相位 <a class="header-anchor" href="#语言建模-→-知识-→-任务向-三相位" aria-label="Permalink to &quot;语言建模 → 知识 → 任务向 三相位&quot;">​</a></h3><p>34B 的 token 账是 <strong>523B + 1053B + 298B ≈ 1.87T</strong>（报告又称约 1.8T 双语）；70B-expr 为 203B + 719B + 347B。相位含义：</p><ul><li><strong>K6 语言建模</strong>：以网页为主的高质量多样本，先让参数落到合理流域，课程式地从易样本开始。</li><li><strong>K61–K63 知识学习</strong>：逐步降低网页比例、提高知识密集源；新源按批到达，所以是离散的 K61/K62/K63，而不是一条连续曲线。</li><li><strong>K64/K65 任务向</strong>：把知识改写成零样本 / 少样本 / 带选项的 QA（FLAN 思路），34B 用 K64，70B 用更保守的 K65，因为 70B 前两段吃得不够、配比剧变会伤分。</li></ul><p>硬件：7B 在 11×8 张 A800-80GB；34B 在 64×8 张 A100-40GB；节点间 2×200 Gbps InfiniBand。聊天版另收指令数据； AquilaChat2-34B 在报告的中英主客观混合基准上对照 LLaMA-2-70B Chat。INT4 量化下 34B 平均分只轻微下降，这是部署侧主张。</p>',16)),(a(),d(A,null,{default:r(()=>[s(l,{id:"mermaid-179",class:"mermaid",graph:"flowchart%20LR%0A%20%20DMU%5B%22DMU%EF%BC%9A%E8%BF%87%E6%BB%A4%20%2F%20%E5%8E%BB%E9%87%8D%20%2F%20%E9%85%8D%E6%AF%94%22%5D%20--%3E%20ATE%5B%22ATE%EF%BC%9A%E5%8F%AF%E6%94%B9%E9%9B%86%E7%BE%A4%E4%B8%8E%E5%88%87%E5%88%86%22%5D%0A%20%20ATE%20--%3E%20TSM%5B%22TSM%EF%BC%9A%E6%8D%9F%E5%A4%B1%20%2F%20%E4%B8%8B%E6%B8%B8%20%2F%20%E6%9D%83%E9%87%8D%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20TSM%20--%3E%7C%22%E5%8A%A0%E6%BA%90%E6%88%96%E6%94%B9%E9%85%8D%E6%AF%94%22%7C%20DMU%0A%20%20ATE%20--%3E%20K6%5B%22K6%20%E8%AF%AD%E8%A8%80%E5%BB%BA%E6%A8%A1%22%5D%0A%20%20K6%20--%3E%20K61%5B%22K61%E2%80%93K63%20%E7%9F%A5%E8%AF%86%22%5D%0A%20%20K61%20--%3E%20K64%5B%22K64%2FK65%20%E4%BB%BB%E5%8A%A1%E5%90%91%22%5D%0A%20%20K64%20--%3E%20CHAT%5B%22AquilaChat2%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>闭环之所以必要，是因为双语预训练的「好配比」会随阶段变。早期需要网页把 n-gram 与句法撑住；中期需要百科与论文把实体密度抬上去；末期需要模板化任务，否则底座不会做选择题。TSM 防止两种误读：损失陡降当成能力跃迁（知识域更易建模），以及损失尖峰当成必须回滚（报告把 70B 早期尖峰更多归因于某类噪声主题，清洗后继续，而不是每次都回到旧检查点）。权重 Fréchet 距离提供第三条证据：若换源后注意力与 MLP 的轨迹仍平滑收敛，说明配比扰动没有把表示推离已学流形。</p><h3 id="gqa-只在-34b-70b-服务账与-7b-不同" tabindex="-1">GQA 只在 34B/70B，服务账与 7B 不同 <a class="header-anchor" href="#gqa-只在-34b-70b-服务账与-7b-不同" aria-label="Permalink to &quot;GQA 只在 34B/70B，服务账与 7B 不同&quot;">​</a></h3><p>34B 的 48 头配 8 组 KV，decode 的 KV 相对 MHA 大约按 \\(8/48\\) 降。7B 仍是 32 头满注意力、窗只有 2K，不能把 34B 的量化故事和 GQA 故事抄到 7B 卡上。词表 10 万相对 LLaMA 32k，中英压缩率更均衡，但嵌入表更大，7B 档参数里词表占比不可忽略。</p><p><span class="marginnote">报告对照写 Aquila2-34B 用少于 LLaMA-2-70B 的 token 在 21 套数据上平均分更好。这是该报告协议下的主张，不是「34B 在所有英文任务上替代 70B」。引用必须带基准集合。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>70B-expr 不是对等放大：token 更少、第三阶段配方不同、异构集群。不要用 34B 的 1.8T 去标注 70B。HeuriMentor 的「实时改配比」依赖他们内部的下游监视集，开源 FlagScale 给了训练栈，并不自动包含当时的数据批次 K6–K65。INT4「几乎不掉点」是 34B 的量化实验，不是 7B/70B 的保证。</p><p>一代 Aquila 与 Aquila2 权重、词表、窗长都可能不兼容，不能当同系列热切换。Chat 模板与 <code>[CLS]</code> 用于客观评测的用法写在报告附录，复现主观分还依赖他们的双语裁判协议。训练代码在 FlagOpen/FlagScale，权在 FlagAI-Open/Aquila2；许可以当时页面为准。</p><p><span class="marginnote"> Aquila2-34B 预训练在 A100-40GB 上切流水线，是因为 60 层×6144 在 40GB 上单卡装不下激活。换 80GB 卡可以把流水段数改掉，但报告数字是 40GB 设定下的 666 token/s/GPU，不要直接当 A800 吞吐量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Aquila2 是智源中英双语系列：7B / 34B / 70B-expr，RoPE + 大词表；34B/70B 用 GQA。</li><li>方法核心是 HeuriMentor：ATE 可改集群，TSM 看损失/下游/权重，DMU 按 K6–K65 换配比。</li><li>34B 约 1.8T，三相位从语言建模到知识再到任务向；70B-expr 是异构与欠 token 的实验档。</li><li>Chat 与 INT4 是报告里的应用结果；不要把 34B 的量化与窗长写给 7B。</li><li>出处：Zhang 等，<em>Aquila2 Technical Report</em>，arXiv:2408.07410；训练栈 FlagScale，权重 FlagAI-Open/Aquila2。</li></ul>',11))])}const b=o(h,[["render",p]]);export{T as __pageData,b as default};
